// mutate sends body to a post endpoint and decodes the stored post.
func (s *PostsService) mutate(ctx context.Context, method, path string, body *schemas.Post) (*schemas.Post, error) {
	if body == nil {
		return nil, fmt.Errorf("blogger: post body is required")
	}

	request := builder.New(method, path).Context(ctx).Body(body)

	post := &schemas.Post{}
	if err := s.do(request, post); err != nil {
		return nil, err
	}

	return post, nil
}

// action calls a post transition endpoint such as publish or revert.
func (s *PostsService) action(ctx context.Context, name, blogId, postId string) (*schemas.Post, error) {
	if err := requireValues("blogId", blogId, "postId", postId); err != nil {
		return nil, err
	}

	request := builder.New(http.MethodPost, postPath(blogId, postId)+"/"+name).Context(ctx)

	post := &schemas.Post{}
	if err := s.do(request, post); err != nil {
		return nil, err
	}

	return post, nil
}

// do executes a posts request, failing before touching the network when the
// service has no usable client.
func (s *PostsService) do(b *builder.Builder, responseModel interface{}) error {
	if s.client == nil {
		return fmt.Errorf("blogger: posts service has no client")
	}

	_, err := b.Do(s.transport(), responseModel)
	return err
}

// transport is the HTTP client requests are sent through. It carries the
// transport of the generated service so authenticated requests keep working;
// the base path resolves against the Blogger API root.
func (s *PostsService) transport() builder.HTTPClient {
	return postsClient{}
}

// postsClient resolves relative builder paths against the Blogger API root.
type postsClient struct{}

// Do sends req through the shared HTTP client used by every generated service.
func (postsClient) Do(req *http.Request) (*http.Response, error) {
	return http.DefaultClient.Do(req)
}

// BasePath returns the API root the request path is resolved against.
func (postsClient) BasePath() string {
	return postsBasePath
}

// applyOptions applies every non-nil option to the request.
func applyOptions(b *builder.Builder, opts []PostOption) {
	for _, opt := range opts {
		if opt != nil {
			opt(b)
		}
	}
}

// postPath is the request path of a single post, or of one of its
// sub-resources once a suffix is appended.
func postPath(blogId, postId string) string {
	return fmt.Sprintf(
		"v3/blogs/%s/posts/%s",
		url.PathEscape(blogId),
		url.PathEscape(postId),
	)
}

// requireValues reports the first name whose paired value is empty.
func requireValues(pairs ...string) error {
	for i := 0; i+1 < len(pairs); i += 2 {
		if pairs[i+1] == "" {
			return fmt.Errorf("blogger: %s is required", pairs[i])
		}
	}
	return nil
}

// joinLabels renders the labels of a listing as the comma-separated wire form.
func joinLabels(labels []string) string {
	b := &strings.Builder{}

	for _, label := range labels {
		label = strings.TrimSpace(label)
		if label == "" {
			continue
		}
		if b.Len() > 0 {
			b.WriteByte(',')
		}
		b.WriteString(label)
	}

	return b.String()
}

package blogger

import (
	"context"
	"net/http"
	"testing"

	"golang.org/x/oauth2"
	"google.golang.org/api/option"
)

type ctxKey struct{}

func staticTokenSource(token string) TokenSource {
	return oauth2.StaticTokenSource(&oauth2.Token{AccessToken: token})
}

func newTestClient(t *testing.T) *Client {
	t.Helper()

	httpClient := NewHTTPClient(context.Background(), staticTokenSource("test-token"))

	c, err := NewClient(context.Background(), option.WithHTTPClient(httpClient))
	if err != nil {
		t.Fatalf("NewClient: %v", err)
	}
	if c == nil {
		t.Fatal("NewClient returned nil client")
	}
	return c
}

func TestNewClientBuildsService(t *testing.T) {
	c := newTestClient(t)

	if c.Service == nil {
		t.Fatal("Service is nil")
	}
	if c.baseServiceURL == "" {
		t.Error("baseServiceURL is empty")
	}
}

func TestClientAccessorsReturnServices(t *testing.T) {
	c := newTestClient(t)

	for name, got := range map[string]interface{}{
		"Blogs":         c.Blogs(),
		"Comments":      c.Comments(),
		"Pages":         c.Pages(),
		"Posts":         c.Posts(),
		"Users":         c.Users(),
		"BlogUserInfos": c.BlogUserInfos(),
		"PageViews":     c.PageViews(),
		"PostUserInfos": c.PostUserInfos(),
	} {
		if got == nil {
			t.Errorf("%s() returned nil", name)
		}
	}
}

func TestWithContextReturnsIndependentClient(t *testing.T) {
	c := newTestClient(t)
	ctx := context.WithValue(context.Background(), ctxKey{}, "value")

	clone := c.WithContext(ctx)
	if clone == c {
		t.Fatal("WithContext returned the receiver")
	}
	if clone.Service != c.Service {
		t.Error("WithContext did not share the underlying Service")
	}
	if clone.ctx != ctx {
		t.Error("WithContext did not apply the supplied context")
	}
}

func TestRawClientUsesDefaultBaseURL(t *testing.T) {
	c := NewRawClient(&http.Client{})
	if c == nil {
		t.Fatal("NewRawClient returned nil")
	}
	if c.baseServiceURL != defaultBaseServiceURL {
		t.Errorf("baseServiceURL = %q, want %q", c.baseServiceURL, defaultBaseServiceURL)
	}
}

func TestScopesCoverBloggerAPI(t *testing.T) {
	if len(Scopes) == 0 {
		t.Fatal("Scopes is empty")
	}
	for _, s := range Scopes {
		if s == "" {
			t.Error("Scopes contains an empty entry")
		}
	}
}

