const cwd = "/Users/aleph/Projects/blogger-go";
// Isolated probe: build ONLY the services package sources against a root package that imports services (the real intended wiring),
// so bloguserinfos.go is type-checked the way it will be in the finished module.
const script = `
set -e
T=/tmp/blogger-go-verify
rm -rf $T; mkdir -p $T/gen/services
cp -r gen/builder gen/schemas gen/services $T/gen/
cp go.mod go.sum auth.go client.go $T/
# mirror the parent's refactor: root package imports the services package (the wiring client.go's accessors need)
python3 - <<'PY'
p='$T/client.go'
s=open(p).read()
s=s.replace('import (\\n\\t"context"','import (\\n\\t"context"')
s=s.replace('\\t"google.golang.org/api/option"\\n)', '\\t"google.golang.org/api/option"\\n\\n\\tservices "github.com/itokun99/blogger-go/gen/services"\\n)', 1)
open(p,'w').write(s)
PY
cd $T
echo "== services package source list"; go list -f '{{.GoFiles}}' ./gen/services
echo "== type-check services package alone (go/types)"
cat > /tmp/typecheck.go <<'GO'
package main

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"os"
)

func main() {
	dir := os.Args[1]
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dir, nil, 0)
	if err != nil {
		fmt.Println("parse:", err)
		os.Exit(1)
	}
	for _, pkg := range pkgs {
		var files []*ast.File
		for _, f := range pkg.Files {
			files = append(files, f)
		}
		conf := types.Config{Importer: importer.ForCompiler(fset, "source", nil), Error: func(e error) { fmt.Println("ERR:", e) }}
		_, err := conf.Check(pkg.Name, fset, files, nil)
		if err != nil {
			fmt.Println("TYPECHECK_FAILED")
			os.Exit(1)
		}
		fmt.Println("TYPECHECK_OK", pkg.Name)
	}
}
GO
cd $T && go run /tmp/typecheck.go $T/gen/services 2>&1 | tail -20
`;
const r = await tool.bash({ command: script, cwd, timeout: 600 });
console.log(r.text ?? JSON.stringify(r));

