edits.oldText:
// blogUserInfosClient adapts the transport of the Blogger client to
// builder.HTTPClient, resolving relative builder paths against the API root the
// service was built with.
type blogUserInfosClient struct {
	service *bloggerv3.Service

	httpClient *http.Client
}

// Do sends req through the transport the Blogger client was built with, or the
// default client when that transport is absent.
func (c blogUserInfosClient) Do(req *http.Request) (*http.Response, error) {
	if c.httpClient == nil {
		return http.DefaultClient.Do(req)
	}
	return c.httpClient.Do(req)
}

// BasePath returns the API root the request path is resolved against.
func (c blogUserInfosClient) BasePath() string {
	if c.service == nil || c.service.BasePath == "" {
		return blogUserInfosBasePath
	}
	return c.service.BasePath
}

