// the service has no usable client.
func (s *BlogUserInfosService) do(b *builder.Builder, responseModel interface{}) error {
	if s.client == nil {
		return fmt.Errorf("blogger: blogUserInfos service has no client")
	}

	_, err := b.Do(s.transport(), responseModel)
	return err
}

// transport is the HTTP client requests are sent through. It prefers the
// caller-supplied HTTP client so its transport is reused, falling back to the
// default client so a service built without credentials still resolves paths
// against the API root.
func (s *BlogUserInfosService) transport() builder.HTTPClient {
	client := blogUserInfosClient{}

	if s.client != nil {
		client.service = s.client.Service

		if httpClient := s.client.HTTPClient(); httpClient != nil {
			client.httpClient = httpClient
		}
	}

	return client
}

